// Nodo function "Autorizar": verifica el token Bearer que envía Gjallarhorn (Alertmanager).
// El valor esperado se lee del entorno del proceso de Node-RED (NORNAS_WEBHOOK_TOKEN) o, si no
// existe, del contexto global. Salida 1 = autorizado, salida 2 = respuesta 401.
const esperado = env.get("NORNAS_WEBHOOK_TOKEN") || global.get("NORNAS_WEBHOOK_TOKEN");
const recibido = (msg.req && msg.req.headers && msg.req.headers.authorization) || "";
if (!esperado || recibido !== "Bearer " + esperado) {
    msg.statusCode = 401;
    msg.payload = { error: "no autorizado" };
    return [null, msg];
}
return [msg, null];

// Nodo function "Alertmanager → estados MQTT". Traduce el webhook de Gjallarhorn a los eventos
// MQTT del contrato de Yggdrasil (docs/02-design/architecture.md):
//   midgard/wan/<id>/estado          saludable|degradado|caido|recuperando   (retained)
//   midgard/wan/<id>/apto_llamadas   si|no                                   (retained)
//   midgard/hogar/internet/estado    ok|degradado|caido                      (retained)
//   midgard/wan/<id>/alerta          JSON {alerta, severidad, desde, detalle} (no retained)
// Salidas: 1 = MQTT (Ratatosk), 2 = notificación push, 3 = respuesta HTTP al webhook.
// Push: un aviso por episodio. Gjallarhorn reenvía el grupo entero en cada cambio del grupo y cada
// repeat_interval (4 h); sin recordar qué se avisó ya, cada reenvío sería un push repetido.
const RECUPERACION_MS = 5 * 60 * 1000;   // Recuperando -> Saludable tras 5 min estable
const OLVIDO_MS = 7 * 24 * 3600 * 1000;  // una huella sin resolución en 7 d se olvida: recordatorio semanal
const PRIORIDAD = { critical: 4, warning: 3, info: 2 };   // prioridades de ntfy (1..5)
// WANs de la plataforma: una WAN de la que no se ha sabido nada cuenta como saludable, para que
// la caida de una sola no deje al hogar en "caido" (YGG_WANS en el entorno del contenedor).
const WANS = (env.get("YGG_WANS") || "wan1,wan2").split(",").map(s => s.trim()).filter(Boolean);
const alertas = (msg.payload && msg.payload.alerts) || [];
const estados = flow.get("estado_wan") || {};
const apto = flow.get("apto_wan") || {};          // ultimo valor conocido de apto_llamadas por WAN
const degradada = flow.get("degradada_wan") || {};  // WanDegradada firing por WAN (para salir de Recuperando)
const timers = context.get("timers") || {};
const avisados = flow.get("avisados") || {};      // huella -> instante del push, mientras siga firing
const ahora = Date.now();
for (const fp of Object.keys(avisados)) if (ahora - avisados[fp] > OLVIDO_MS) delete avisados[fp];
const mqtt = [];
const push = [];

function calcHogar(e) {
    const v = WANS.map(w => e[w] || "saludable");
    if (v.every(x => x === "caido")) return "caido";
    if (v.some(x => x === "saludable")) return "ok";
    return "degradado";
}
function m(topic, payload, retain) {
    return { topic, payload: typeof payload === "string" ? payload : JSON.stringify(payload), qos: 1, retain: !!retain };
}
function fijar(wan, estado) { estados[wan] = estado; mqtt.push(m(`midgard/wan/${wan}/estado`, estado, true)); }
function aviso(titulo, texto, prioridad, etiquetas) {
    push.push({ topic: titulo, payload: texto, prioridad: prioridad || 3, etiquetas: etiquetas || [] });
}

for (const a of alertas) {
    const l = a.labels || {}, an = a.annotations || {};
    const wan = l.wan, nombre = l.alertname, firing = a.status === "firing";
    if (!nombre) continue;
    const prio = PRIORIDAD[l.severity] || 3;
    // nueva = primera vez que se ve firing; resuelta = se había avisado y ahora se resuelve
    const fp = a.fingerprint || JSON.stringify(l);
    const nueva = firing && !avisados[fp];
    const resuelta = !firing && !!avisados[fp];
    if (firing) { if (nueva) avisados[fp] = ahora; } else delete avisados[fp];
    if (!wan) {                                   // p. ej. SondaCaida o las de Bragi: aviso y resolución
        if (nueva) aviso(`Heimdall: ${nombre}`, an.resumen || "", prio, ["warning"]);
        if (resuelta) aviso(`Heimdall: ${nombre} resuelta`, an.resumen || "", 2, ["white_check_mark"]);
        continue;
    }
    if (firing) mqtt.push(m(`midgard/wan/${wan}/alerta`, { alerta: nombre, severidad: l.severity || "", desde: a.startsAt, detalle: an.resumen || "" }, false));
    switch (nombre) {
        case "WanCaida":
            if (timers[wan]) { clearTimeout(timers[wan]); delete timers[wan]; }
            if (firing) {
                fijar(wan, "caido");
                mqtt.push(m(`midgard/wan/${wan}/apto_llamadas`, "no", true));   // caida => no apta
                if (nueva) aviso(`Heimdall: ${wan} CAÍDA`, an.descripcion || an.resumen || "", prio, ["rotating_light"]);
            } else {
                fijar(wan, "recuperando");
                timers[wan] = setTimeout(() => {
                    const e = flow.get("estado_wan") || {};
                    const t = context.get("timers") || {};
                    delete t[wan]; context.set("timers", t);
                    if (e[wan] !== "recuperando") return;
                    // Si la degradacion sigue activa al terminar la recuperacion, el enlace queda Degradado
                    const final = ((flow.get("degradada_wan") || {})[wan]) ? "degradado" : "saludable";
                    e[wan] = final; flow.set("estado_wan", e);
                    const ap = (flow.get("apto_wan") || {})[wan];
                    node.send([[m(`midgard/wan/${wan}/estado`, final, true),
                                m(`midgard/wan/${wan}/apto_llamadas`, ap === false ? "no" : "si", true),
                                m("midgard/hogar/internet/estado", calcHogar(e), true)], null, null]);
                }, RECUPERACION_MS);
                // Sin exigir "resuelta": tras reiniciar Nornas no recuerda la caída y el aviso importa igual
                aviso(`Heimdall: ${wan} recuperando`, "Las sondas responden; si sigue estable 5 min pasa a saludable.",
                      2, ["white_check_mark"]);
            }
            break;
        case "WanDegradada":
            degradada[wan] = firing;
            if (estados[wan] === "caido" || estados[wan] === "recuperando") break;
            fijar(wan, firing ? "degradado" : "saludable");
            if (nueva) aviso(`Heimdall: ${wan} degradada`, an.resumen || "", prio, ["warning"]);
            break;
        case "WanNoAptaLlamadas":
            apto[wan] = !firing;
            mqtt.push(m(`midgard/wan/${wan}/apto_llamadas`, firing ? "no" : "si", true));
            break;
        case "WanThroughputBajo":
        case "SleipnirSinMedicion":
            if (nueva) aviso(`Heimdall: ${nombre} en ${wan}`, an.resumen || "", prio, ["warning"]);
            break;
        // Discrepancia entre Heimdall y la ruta del balanceador (Thor): no cambian el estado MQTT
        // de la WAN, que es el de Heimdall; avisan al empezar y al resolverse.
        case "WanSanaFueraDeRuta":
        case "WanCaidaEnRuta":
            if (nueva) aviso(`Heimdall: ${nombre} en ${wan}`, an.resumen || "", prio, ["warning"]);
            if (resuelta) aviso(`Heimdall: ${nombre} en ${wan} resuelta`, an.resumen || "", 2, ["white_check_mark"]);
            break;
        default:
            break;
    }
}
flow.set("estado_wan", estados);
flow.set("apto_wan", apto);
flow.set("degradada_wan", degradada);
flow.set("avisados", avisados);
context.set("timers", timers);
mqtt.push(m("midgard/hogar/internet/estado", calcHogar(estados), true));
msg.statusCode = 200;
msg.payload = { ok: true, alertas: alertas.length };
return [mqtt, push, msg];

// Nodo function "Formatear ntfy": convierte un aviso de la salida push de "traducir" en una
// publicación JSON de ntfy, que el nodo http request siguiente envía.
//   entrada:  { topic: título, payload: texto, prioridad: 1..5, etiquetas: [...] }
//   NTFY_URL: URL completa del tema (https://ntfy.sh/<tema>), del entorno del contenedor.
// Se publica en JSON contra la raíz del servidor y no con cabeceras Title/Tags: las cabeceras HTTP
// no admiten bien UTF-8 y los títulos llevan tildes ("CAÍDA").
// El tema ES la credencial (quien lo conozca lee los avisos): no se registra nunca, ni en el
// estado del nodo ni en avisos.
const url = env.get("NTFY_URL") || "";
if (!url) {
    node.status({ fill: "grey", shape: "ring", text: "sin NTFY_URL: push desactivado" });
    return null;
}
const partes = url.match(/^(https?:\/\/[^/]+)\/([^/?#]+)\/?$/);
if (!partes) {
    node.status({ fill: "red", shape: "dot", text: "NTFY_URL no tiene la forma https://servidor/tema" });
    return null;
}
msg.url = partes[1] + "/";
msg.method = "POST";
msg.headers = { "Content-Type": "application/json" };
msg.payload = JSON.stringify({
    topic: partes[2],
    title: msg.topic || "Heimdall",
    message: msg.payload || msg.topic || "",
    priority: msg.prioridad || 3,
    tags: msg.etiquetas || [],
});
node.status({ fill: "blue", shape: "dot", text: "enviando: " + (msg.topic || "") });
return msg;

// Nodo function "Respuesta de ntfy": deja constancia de si ntfy aceptó el aviso. Un fallo va a
// node.warn, que llega al log del contenedor (docker logs yggdrasil-node-red). Solo se registra el
// código y el título, nunca la URL: lleva el tema, que es la credencial.
// Con un error de red, http request pone en statusCode el código del error (p. ej. "ENOTFOUND").
const codigo = msg.statusCode;
if (typeof codigo === "number" && codigo >= 200 && codigo < 300) {
    node.status({ fill: "green", shape: "dot", text: `ntfy ${codigo}: ${msg.topic || ""}` });
} else {
    node.status({ fill: "red", shape: "dot", text: `ntfy ${codigo || "sin respuesta"}` });
    node.warn(`ntfy rechazó el aviso "${msg.topic || ""}": ${codigo || "sin respuesta"}`);
}
return null;

// Nodo function "Autorizar tablero": token de solo lectura de Hlidskjalf (HLIDSKJALF_TOKEN), que
// la página manda como Bearer. Es otro token que el del webhook: quien lo tenga ve el estado de
// midgard, pero no puede inyectar alertas. Sin token configurado, o con uno corto, el tablero
// queda cerrado (503) en vez de abierto. Salida 1 = autorizado, salida 2 = respuesta de error.
const esperado = env.get("HLIDSKJALF_TOKEN") || "";
const igual = global.get("secretoIgual");
const cabecera = (msg.req && msg.req.headers && msg.req.headers.authorization) || "";
const recibido = cabecera.startsWith("Bearer ") ? cabecera.slice(7) : "";
msg.headers = { "Cache-Control": "no-store" };
if (esperado.length < 32 || typeof igual !== "function") {
    msg.statusCode = 503;
    msg.payload = { error: "tablero sin configurar: falta HLIDSKJALF_TOKEN (32 caracteres o más) en Nornas" };
    return [null, msg];
}
if (!recibido || !igual(recibido, esperado)) {
    msg.statusCode = 401;
    msg.payload = { error: "no autorizado" };
    return [null, msg];
}
return [msg, null];

// Nodo function "Resumen de midgard" del tablero Hlidskjalf: una consulta instantánea a Mimir con
// todas las series que pinta la tablet y la lista de alertas activas de Gjallarhorn, convertidas
// en un JSON pequeño. La tablet (Galaxy Tab 2, 1 GB de RAM) no habla PromQL ni carga Grafana:
// recibe solo lo que dibuja. Si una fuente no responde, su sección va vacía y `fuentes` lo dice;
// el tablero lo muestra en vez de dar por buena una pantalla en verde.
const consultar = global.get("consultarJson");
const MIMIR = env.get("HLIDSKJALF_MIMIR_URL") || "http://mimir:9090";
const GJALLARHORN = env.get("HLIDSKJALF_GJALLARHORN_URL") || "http://gjallarhorn:9093";

const SERIES = [
    "wan:up", "wan:perdida_pct:5m", "wan:latencia_p95:5m", "wan:disponibilidad:30d", "wan:slo_throughput_mbps",
    "hogar:up", "hogar:disponibilidad:30d",
    "wan_throughput_mbps", "wan_throughput_ultima_medicion_timestamp_seconds", "wan_throughput_medicion_en_curso",
    "yggdrasil_wan_en_ruta", "yggdrasil_thor_timestamp_seconds",
    "yggdrasil_smart_atributo", "yggdrasil_smart_salud", "yggdrasil_smart_lectura_ok",
    "yggdrasil_fs_montado", "yggdrasil_fs_tamano_bytes", "yggdrasil_fs_libre_bytes",
    "yggdrasil_disco_rotacional", "yggdrasil_disco_errores_kernel_15m",
    "yggdrasil_servicio_ok", "yggdrasil_respaldo_ultimo_exito_timestamp_seconds",
];
// Atributos SMART que enseña el tablero (los que publica Thor y vigila DiscoEmpeora, más contexto).
const SMART = { 5: "reasignados", 187: "no_corregidos", 197: "pendientes", 198: "incorregibles", 199: "errores_cable", 194: "temperatura_c", 9: "horas" };
const GRAVEDAD = { critical: 0, warning: 1, info: 2 };

const consulta = `{__name__=~"${SERIES.join("|")}"}`;
const [prom, am] = await Promise.allSettled([
    consultar(`${MIMIR}/api/v1/query?query=${encodeURIComponent(consulta)}`, 5000),
    consultar(`${GJALLARHORN}/api/v2/alerts?active=true&silenced=false&inhibited=false`, 5000),
]);

const ahora = Math.round(Date.now() / 1000);
const mimirOk = prom.status === "fulfilled" && prom.value && prom.value.status === "success";
const series = mimirOk ? prom.value.data.result : [];
const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : null; };
const de = (nombre, filtro = {}) => series.filter((s) => s.metric.__name__ === nombre &&
    Object.entries(filtro).every(([k, v]) => s.metric[k] === v));
const valor = (nombre, filtro) => { const s = de(nombre, filtro)[0]; return s ? num(s.value[1]) : null; };
const hace = (ts) => (ts === null ? null : Math.max(0, ahora - ts));

const wans = [...new Set(series.filter((s) => s.metric.wan && /^wan[0-9]+$/.test(s.metric.wan)).map((s) => s.metric.wan))].sort();
const wan = wans.map((w) => {
    const latencia = valor("wan:latencia_p95:5m", { wan: w });
    return {
        wan: w,
        up: valor("wan:up", { wan: w }),
        en_ruta: valor("yggdrasil_wan_en_ruta", { wan: w }),
        perdida_pct: valor("wan:perdida_pct:5m", { wan: w }),
        latencia_p95_ms: latencia === null ? null : Math.round(latencia * 10000) / 10,
        disponibilidad_30d: valor("wan:disponibilidad:30d", { wan: w }),
        bajada_mbps: valor("wan_throughput_mbps", { wan: w, direccion: "down" }),
        subida_mbps: valor("wan_throughput_mbps", { wan: w, direccion: "up" }),
        slo_bajada_mbps: valor("wan:slo_throughput_mbps", { wan: w, direccion: "down" }),
        slo_subida_mbps: valor("wan:slo_throughput_mbps", { wan: w, direccion: "up" }),
        medicion_hace_s: hace(valor("wan_throughput_ultima_medicion_timestamp_seconds", { wan: w })),
        sleipnir_midiendo: valor("wan_throughput_medicion_en_curso", { wan: w }),
    };
});

const discos = [...new Set(de("yggdrasil_smart_lectura_ok").map((s) => s.metric.disco))].sort().map((d) => {
    const disco = { disco: d, lectura_ok: valor("yggdrasil_smart_lectura_ok", { disco: d }), salud: valor("yggdrasil_smart_salud", { disco: d }) };
    for (const [id, clave] of Object.entries(SMART)) disco[clave] = valor("yggdrasil_smart_atributo", { disco: d, id });
    disco.rotacional = valor("yggdrasil_disco_rotacional", { disco: d });
    disco.errores_kernel = valor("yggdrasil_disco_errores_kernel_15m", { disco: d });
    return disco;
});
const fs = de("yggdrasil_fs_montado").map((s) => s.metric.punto).sort().map((p) => ({
    punto: p,
    montado: valor("yggdrasil_fs_montado", { punto: p }),
    tamano_bytes: valor("yggdrasil_fs_tamano_bytes", { punto: p }),
    libre_bytes: valor("yggdrasil_fs_libre_bytes", { punto: p }),
}));
// Un respaldo por etiqueta `respaldo` (Yggdrasil, Bifrost...). Sin etiqueta es el de Yggdrasil:
// así lo publicaba Thor antes de admitir varios.
const respaldos = de("yggdrasil_respaldo_ultimo_exito_timestamp_seconds")
    .map((s) => {
        const ts = num(s.value[1]);
        return { nombre: s.metric.respaldo || "yggdrasil", ultimo_exito: ts, hace_h: ts === null ? null : Math.floor(hace(ts) / 3600) };
    })
    .sort((a, b) => (a.nombre === "yggdrasil" ? -1 : b.nombre === "yggdrasil" ? 1 : a.nombre.localeCompare(b.nombre)));
const respaldo = respaldos.find((r) => r.nombre === "yggdrasil") || { ultimo_exito: null, hace_h: null };
const servicios = de("yggdrasil_servicio_ok")
    .map((s) => ({ tipo: s.metric.tipo, nombre: s.metric.nombre, ok: num(s.value[1]) }))
    .sort((a, b) => (a.tipo === b.tipo ? a.nombre.localeCompare(b.nombre) : a.tipo === "contenedor" ? -1 : 1));

const amOk = am.status === "fulfilled" && Array.isArray(am.value);
const alertas = (amOk ? am.value : [])
    .map((a) => ({
        nombre: a.labels.alertname,
        severidad: a.labels.severity || "warning",
        wan: a.labels.wan || null,
        resumen: (a.annotations && a.annotations.resumen) || a.labels.alertname,
        desde: a.startsAt,
    }))
    .sort((a, b) => ((GRAVEDAD[a.severidad] ?? 1) - (GRAVEDAD[b.severidad] ?? 1)) || String(a.desde).localeCompare(String(b.desde)));

msg.payload = {
    version: 1,
    generado: ahora,
    fuentes: { mimir: mimirOk, gjallarhorn: amOk },
    hogar: { up: valor("hogar:up"), disponibilidad_30d: valor("hogar:disponibilidad:30d") },
    wan,
    alertas,
    host: {
        thor_hace_s: hace(valor("yggdrasil_thor_timestamp_seconds")),
        discos,
        fs,
        // `respaldo` (solo el de Yggdrasil) queda para la tablet que aún tenga cargado el tablero viejo
        respaldo: { ultimo_exito: respaldo.ultimo_exito, hace_h: respaldo.hace_h },
        respaldos,
    },
    servicios,
};
// Un aviso por cambio de estado de cada fuente, no uno por consulta (la tablet pide cada 15 s).
const antes = context.get("fuentes") || { mimir: true, gjallarhorn: true };
const motivo = (r, otro) => (r.status === "rejected" ? r.reason.message : otro);
if (antes.mimir !== mimirOk) node.warn(mimirOk ? "Hlidskjalf: Mimir responde de nuevo" : `Hlidskjalf: Mimir no respondió (${motivo(prom, "respuesta sin datos")})`);
if (antes.gjallarhorn !== amOk) node.warn(amOk ? "Hlidskjalf: Gjallarhorn responde de nuevo" : `Hlidskjalf: Gjallarhorn no respondió (${motivo(am, "respuesta inesperada")})`);
context.set("fuentes", { mimir: mimirOk, gjallarhorn: amOk });
msg.statusCode = 200;
msg.headers = { "Cache-Control": "no-store" };
return msg;
